//! Zone-geometry resolution for zone-only alerts.
//!
//! Many NWS products (most watches and advisories, special weather statements,
//! marine and fire-weather alerts) are issued against UGC *zones* rather than a
//! drawn polygon, so the active-alerts feed returns them with null geometry. The
//! API has no bulk-geometry endpoint — resolving each referenced zone over the
//! network would mean ~1k requests for a typical national alert set.
//!
//! Instead the zone polygons are baked into the binary: a simplified geometry
//! table generated by `tools/build_zone_geometry.py` from the official NWS
//! shapefiles. Resolution is then a pure local lookup, no network involved.

use std::collections::HashMap;

use geo::BooleanOps;

use super::types::{Alert, AlertGeometry, Ring};

/// Simplified NWS zone polygons, generated by `tools/build_zone_geometry.py`.
/// A JSON map of "<type>/<id>" (matching the tail of an alert's affectedZones
/// URL, e.g. "forecast/ALZ019") to a list of polygons, each a list of rings,
/// each ring a list of `[lon, lat]` pairs. ~1.2 MB gzipped over the wire.
static ZONE_GEOMETRY_JSON: &[u8] = include_bytes!("../../assets/zone_geometry.json");

/// On-disk shape of [`ZONE_GEOMETRY_JSON`]: zone key -> polygons -> rings -> pts.
type RawZones = HashMap<String, Vec<Vec<Vec<(f64, f64)>>>>;

/// Resolves footprints for zone-only alerts from the baked geometry table.
/// The table is parsed lazily on first use so it costs nothing until an alert
/// actually needs it.
#[derive(Default)]
pub struct ZoneResolver {
    zones: HashMap<String, AlertGeometry>,
    loaded: bool,
}

impl ZoneResolver {
    pub fn new() -> Self {
        Self::default()
    }

    /// Fill in geometry for any zone-only alert by stitching together its
    /// referenced zones' polygons. Returns true if any alert's geometry changed.
    pub fn resolve(&mut self, alerts: &mut [Alert]) -> bool {
        // Nothing to do (and no reason to pay the one-time parse) unless some
        // alert is still missing a footprint but lists zones to resolve from.
        let needs = alerts
            .iter()
            .any(|a| a.geometry.is_empty() && !a.affected_zones.is_empty());
        if !needs {
            return false;
        }
        self.ensure_loaded();

        let mut changed = false;
        for alert in alerts.iter_mut() {
            if !alert.geometry.is_empty() || alert.affected_zones.is_empty() {
                continue;
            }
            let mut merged = AlertGeometry::default();
            for url in &alert.affected_zones {
                if let Some(geom) = zone_key(url).and_then(|k| self.zones.get(k)) {
                    merged.polygons.extend(geom.polygons.iter().cloned());
                }
            }
            if !merged.polygons.is_empty() {
                // Dissolve the many adjacent zone polygons into the alert's outer
                // perimeter(s) so a watch over dozens of counties draws one clean
                // outline instead of dozens with noisy internal borders.
                merged.polygons = dissolve_polygons(merged.polygons);
                merged.recompute_bbox();
                alert.geometry = merged;
                changed = true;
            }
        }
        changed
    }

    /// Parse the baked geometry table into the lookup map, once.
    fn ensure_loaded(&mut self) {
        if self.loaded {
            return;
        }
        self.loaded = true;
        match serde_json::from_slice::<RawZones>(ZONE_GEOMETRY_JSON) {
            Ok(raw) => {
                self.zones = raw
                    .into_iter()
                    .map(|(key, polygons)| {
                        let mut geom = AlertGeometry {
                            polygons,
                            bbox: None,
                        };
                        geom.recompute_bbox();
                        (key, geom)
                    })
                    .collect();
                log::info!("loaded {} alert zone geometries", self.zones.len());
            }
            Err(e) => log::error!("failed to parse bundled zone geometry: {}", e),
        }
    }
}

/// Extract the "<type>/<id>" lookup key from an affectedZones URL such as
/// `https://api.weather.gov/zones/forecast/ALZ019`.
fn zone_key(url: &str) -> Option<&str> {
    url.split("/zones/").nth(1)
}

/// Dissolve a set of polygons (in our `[outer, hole, …]` ring form) into the
/// union of their areas, removing shared internal borders. Returns the input
/// unchanged when there's nothing to merge or the union comes back empty (so an
/// alert never loses its footprint).
fn dissolve_polygons(polygons: Vec<Vec<Ring>>) -> Vec<Vec<Ring>> {
    if polygons.len() < 2 {
        return polygons;
    }
    let mp = to_multipolygon(&polygons);
    // Fold the members together one at a time: each union dissolves the shared
    // edge between the accumulated area and the next polygon. (geo 0.29 has no
    // `unary_union`, and a MultiPolygon's `union` assumes its members don't
    // overlap, which independently-simplified zone borders may violate.)
    let mut acc = geo::MultiPolygon::new(Vec::new());
    for poly in &mp.0 {
        acc = acc.union(poly);
    }
    let out = from_multipolygon(&acc);
    if out.is_empty() {
        polygons
    } else {
        out
    }
}

/// Convert our `[outer, hole, …]` ring form to a `geo::MultiPolygon`.
fn to_multipolygon(polygons: &[Vec<Ring>]) -> geo::MultiPolygon<f64> {
    let polys = polygons
        .iter()
        .filter_map(|rings| {
            let mut iter = rings.iter();
            let exterior = geo::LineString::from(iter.next()?.clone());
            let interiors = iter.map(|r| geo::LineString::from(r.clone())).collect();
            Some(geo::Polygon::new(exterior, interiors))
        })
        .collect();
    geo::MultiPolygon::new(polys)
}

/// Convert a `geo::MultiPolygon` back to our `[outer, hole, …]` ring form.
fn from_multipolygon(mp: &geo::MultiPolygon<f64>) -> Vec<Vec<Ring>> {
    mp.0.iter()
        .map(|poly| {
            let mut rings = vec![poly.exterior().coords().map(|c| (c.x, c.y)).collect()];
            for hole in poly.interiors() {
                rings.push(hole.coords().map(|c| (c.x, c.y)).collect());
            }
            rings
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::alerts::AlertSeverity;
    use wasm_bindgen_test::wasm_bindgen_test;

    fn zone_only_alert(zones: &[&str]) -> Alert {
        Alert {
            id: "test".into(),
            event: "Flood Watch".into(),
            headline: String::new(),
            description: String::new(),
            instruction: String::new(),
            severity: AlertSeverity::Moderate,
            urgency: String::new(),
            certainty: String::new(),
            area_desc: String::new(),
            sender: String::new(),
            effective_secs: None,
            onset_secs: None,
            expires_secs: None,
            ends_secs: None,
            geometry: AlertGeometry::default(),
            affected_zones: zones.iter().map(|z| z.to_string()).collect(),
        }
    }

    #[wasm_bindgen_test]
    fn zone_key_extracts_type_and_id() {
        assert_eq!(
            zone_key("https://api.weather.gov/zones/forecast/ALZ019"),
            Some("forecast/ALZ019")
        );
        assert_eq!(zone_key("not-a-zone-url"), None);
    }

    #[wasm_bindgen_test]
    fn resolve_fills_geometry_from_baked_table() {
        // ALZ019 (Calhoun, AL) is a known forecast zone in the baked table.
        let mut alerts = vec![zone_only_alert(&[
            "https://api.weather.gov/zones/forecast/ALZ019",
        ])];
        let mut resolver = ZoneResolver::new();
        assert!(resolver.resolve(&mut alerts));
        assert!(!alerts[0].geometry.is_empty());
        assert!(alerts[0].geometry.bbox.is_some());
    }

    #[wasm_bindgen_test]
    fn resolve_noop_without_zone_only_alerts() {
        let mut resolver = ZoneResolver::new();
        // An alert that already has geometry (no zones) needs no resolution.
        let mut already = zone_only_alert(&[]);
        already.geometry.polygons.push(vec![vec![(0.0, 0.0); 4]]);
        already.geometry.recompute_bbox();
        let mut alerts = vec![already];
        assert!(!resolver.resolve(&mut alerts));
    }

    #[wasm_bindgen_test]
    fn dissolve_merges_two_adjacent_squares() {
        // Two unit squares sharing the x=1 edge dissolve into one rectangle.
        let left: Ring = vec![(0.0, 0.0), (1.0, 0.0), (1.0, 1.0), (0.0, 1.0), (0.0, 0.0)];
        let right: Ring = vec![(1.0, 0.0), (2.0, 0.0), (2.0, 1.0), (1.0, 1.0), (1.0, 0.0)];
        let out = dissolve_polygons(vec![vec![left], vec![right]]);
        assert_eq!(
            out.len(),
            1,
            "adjacent squares should merge into one polygon"
        );

        // The merged exterior spans the full 0..2 width.
        let xs: Vec<f64> = out[0][0].iter().map(|&(x, _)| x).collect();
        let max_x = xs.iter().cloned().fold(f64::MIN, f64::max);
        let min_x = xs.iter().cloned().fold(f64::MAX, f64::min);
        assert!((min_x - 0.0).abs() < 1e-6 && (max_x - 2.0).abs() < 1e-6);
    }

    #[wasm_bindgen_test]
    fn dissolve_single_polygon_is_unchanged() {
        let square: Ring = vec![(0.0, 0.0), (1.0, 0.0), (1.0, 1.0), (0.0, 1.0), (0.0, 0.0)];
        let polys = vec![vec![square]];
        assert_eq!(dissolve_polygons(polys.clone()), polys);
    }

    #[wasm_bindgen_test]
    fn resolve_leaves_unknown_zone_unresolved() {
        let mut alerts = vec![zone_only_alert(&[
            "https://api.weather.gov/zones/forecast/ZZZ999",
        ])];
        let mut resolver = ZoneResolver::new();
        assert!(!resolver.resolve(&mut alerts));
        assert!(alerts[0].geometry.is_empty());
    }
}
